  });

  test("feature flags are optional — omitting them yields os x version only", () => {
    const combos = expandCombinations({
      os: ["windows-latest"],
      languageVersions: ["3.12"],
    });

    expect(combos).toEqual([{ os: "windows-latest", "language-version": "3.12" }]);
  });
});

